window.DGNL_DE_MON["l6"] = {"id": "l6", "ten": "Đề thi thử số 6", "tv": [{"noiDungChung": null, "cauHoi": [{"question": "Hình tượng người lính Tây Tiến trong đoạn thơ dưới đây có điểm nào khác biệt rõ nhất so với đặc trưng bút pháp thường thấy của văn học cách mạng giai đoạn 1945-1975?<br><i>“Tây Tiến đoàn binh không mọc tóc</i><br><i>Quân xanh màu lá dữ oai hùm</i><br><i>Mắt trừng gửi mộng qua biên giới</i><br><i>Đêm mơ Hà Nội dáng kiều thơm</i><br><i>Rải rác biên cương mồ viễn xứ</i><br><i>Chiến trường đi chẳng tiếc đời xanh</i><br><i>Áo bào thay chiếu anh về đất</i><br><i>Sông Mã gầm lên khúc độc hành”</i><br>(Tây Tiến, Quang Dũng)", "choices": ["Khắc họa người lính ở phương diện sử thi, nhấn mạnh tinh thần chiến đấu và lí tưởng cộng đồng cao hơn đời sống cá nhân.", "Tập trung làm nổi bật vẻ đẹp lãng mạn, bi tráng, đồng thời vẫn giữ nguyên hình ảnh người lính như người anh hùng cách mạng lí tưởng.", "Thể hiện cái nhìn trực diện về mất mát và tình cảm riêng tư, tạo nên hình tượng người lính vừa hào hùng, vừa đời thường.", "Xây dựng hình tượng người lính dựa trên cảm hứng lãng mạn cách mạng, vượt qua mọi khó khăn, hiểm trở."], "correctIndex": 2, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Thể thơ __________ là sự sáng tạo của các tác giả Việt Nam trên cơ sở kế thừa thơ Đường luật, ra đời khoảng thế kỉ XIII. Đại diện tiêu biểu trong việc sáng tạo bằng thể thơ này là Nguyễn Trãi.", "choices": ["Thất ngôn xen lục ngôn", "Lục bát", "Song thất lục bát", "Lục ngôn"], "correctIndex": 0, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "“An thất hứa. Vì vậy, mọi người không còn tin tưởng An.”<br>Chọn phương án chuyển hai câu sau thành một câu ghép đúng về ngữ pháp và giữ nguyên ý nghĩa.", "choices": ["Vì những lần thất hứa trước đây, An đã đánh mất niềm tin của mọi người.", "An đã đánh mất niềm tin của mọi người do thất hứa nhiều lần.", "Mọi người mất niềm tin vào An nên An mới thất hứa.", "Vì An thất hứa nhiều lần, mọi người không còn tin tưởng An."], "correctIndex": 3, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Chọn phương án chứa từ “chân” mang nghĩa chuyển dựa trên phương thức hoán dụ.", "choices": ["Anh ta là một chân bóng đá cừ khôi.", "Người gì đâu mà chân tay vụng về thế!", "Chân trời mới đang chờ đợi phía trước.", "Anh ta kê một miếng giấy dưới chân bàn."], "correctIndex": 0, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "“Màn phát biểu lấy đi nhiều nước mắt của cô Đinh Thị Kim Phấn là một khoảnh khắc đáng nhớ tại buổi trao giải.”<br>Đây là câu _________.<br>Hãy chọn phương án để điền vào chỗ trống.", "choices": ["sai ngữ pháp", "sai logic", "mơ hồ cấu trúc", "sai quy chiếu"], "correctIndex": 2, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Chọn câu đúng.", "choices": ["Trước giây phút lâm trung, ông cụ đã dặn dò con cái phải làm người tử tế.", "Quá trình làm việc tại công ty của An đã diễn ra suôn sẻ, cậu nhận được nhiều lời khen từ cấp trên.", "Những năm tháng bươn trải nơi đất khách đã giúp anh trưởng thành và mạnh mẽ hơn.", "Việc ứng dụng công nghệ tối tân nhất đã góp phần nâng cao hiệu quả quản lý đô thị."], "correctIndex": 1, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Chọn phương án chứa từ “chính” có từ trái nghĩa là “tà” (mờ ám, không đúng đắn).", "choices": ["Nhân vật chính trong câu chuyện là Thuý Kiều.", "Đi vào từ cổng chính, anh sẽ ngay lập tức thấy hội trường.", "Chính mắt tôi thấy cuốn sách ấy từng được trưng bày trước cửa hàng.", "Văn hóa liêm chính là một văn hoá cần thiết ở môi trường học thuật."], "correctIndex": 3, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<i>Người xưa nói, Thăng Long </i><b><i>phi chiến địa</i></b><i>, nhưng Thăng Long – Hà Nội luôn diễn ra những trận đánh ác liệt nhất, những trận quyết chiến chiến lược. </i>(Nỗi nhớ hoa đào, Nguyễn Sĩ Đại)<br>Từ in đậm có ý nghĩa là gì?", "choices": ["Vùng đất thường xuyên xảy ra chiến tranh", "Nơi không phải là chiến trường", "Nơi giao thương, buôn bán", "Vùng đất có vị trí quân sự trọng yếu"], "correctIndex": 1, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Sau khi nhận được bằng khen, cô hiệu trưởng cùng các bạn học sinh đoạt giải cùng nhau chụp một bức hình.<br>Câu trên mắc lỗi gì?", "choices": ["Sai ngữ pháp", "Sai logic", "Sai quy chiếu", "Câu trên không mắc lỗi"], "correctIndex": 2, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Đâu là phương án sửa phù hợp nhất cho câu sai: “Nguyễn Du không chỉ để lại dấu ấn sâu đậm qua Truyện Kiều mà còn thơ chữ Hán của ông thể hiện giọng điệu trầm tư và cảm hứng nhân đạo sâu sắc, cho thấy một tâm hồn luôn trăn trở trước thời cuộc.”", "choices": ["Nguyễn Du không chỉ để lại dấu ấn sâu đậm qua Truyện Kiều, mà thơ chữ Hán của ông với giọng điệu trầm tư và cảm hứng nhân đạo sâu sắc cho thấy một tâm hồn luôn trăn trở trước thời cuộc và số phận con người.", "Nguyễn Du không chỉ để lại dấu ấn sâu đậm qua Truyện Kiều mà thơ chữ Hán của ông, với giọng điệu trầm tư và cảm hứng nhân đạo sâu sắc, còn cho thấy một tâm hồn luôn trăn trở trước thời cuộc và số phận con người.", "Không chỉ để lại dấu ấn sâu đậm qua Truyện Kiều mà Nguyễn Du còn để lại thơ chữ Hán, với giọng điệu trầm tư và cảm hứng nhân đạo sâu sắc, cho thấy một tâm hồn luôn trăn trở trước thời cuộc và số phận con người.", "Bên cạnh việc để lại dấu ấn qua Truyện Kiều, thơ chữ Hán của Nguyễn Du, với giọng điệu trầm tư và cảm hứng nhân đạo sâu sắc, cho thấy một tâm hồn luôn trăn trở trước thời cuộc và số phận con người."], "correctIndex": 1, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Chọn câu đúng.", "choices": ["Ngôi làng nhỏ nằm giữa thâm sâu cùng cốc vẫn giữ được những phong tục cổ truyền qua nhiều thế hệ.", "Anh quyết định đơn phương độc mã lên thành phố lập nghiệp, mang theo khát vọng đổi đời.", "Anh đừng vội làm lớn chuyện, kẻo rút dây động dừng thì hỏng.", "Không thích ồn ào đông đúc, người hiện đại tìm đến những chốn sơn cùng thuỷ tận để mưu cầu một chút bình yên."], "correctIndex": 3, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Chọn câu chứa phong cách ngôn ngữ trang trọng.", "choices": ["Mai chúng ta trao đổi thêm về vấn đề này khi có đủ thông tin cần thiết.", "Tôi phiền anh xem lại giúp tôi nội dung này để tránh hiểu lầm.", "Kính đề nghị Quý cơ quan xem xét và phản hồi bằng văn bản trong thời gian sớm nhất.", "Tôi bảo chú này, nên suy nghĩ thật kĩ trước khi đưa ra quyết định cuối cùng."], "correctIndex": 2, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<br>CÚC: - Ông Hãn đang đợi, chắc nội đêm nay, ông ấy sẽ đến gặp ông, nói chuyện.<br>NGUYỄN TRÃI: -... Đồng bằng qua cơn lửa. Cây cỏ đều thơm lại... Thật ra vẫn là cây cỏ ấy, chỉ có nhận ra được là không phải dễ. Có phải không cô? Nhìn cho thấu một con người không dễ chút nào, thời buổi này, người ta hay có nhiều bộ mặt. Dùng con mắt nào mà nhìn bây giờ?<br>CÚC: - Dạ vâng, lòng người có thước nào đo được. Cái mà quanh co của con người thật ghê gớm. Mà lòng thương của con người, cũng không cùng... Tôi nghĩ, có nhẽ con người ta còn có hai mắt khác nữa, hai con mắt này mở ra thì nhìn được vào lòng người.<br>NGUYỄN TRÃI: - Nghe cô mà tôi thầm giật mình. Có khi càng lọc lõi, khôn ngoan thì hai con mắt mình lại tối mờ đi... Hay là vì tôi đã phải chống chọi quá nhiều! Có khi cứ ngây thơ, trong trẻo, mà lại nhìn rõ.<br>CÚC: - Cũng có khi người phải tự chống chọi với mình để mà sống...<br>NGUYỄN TRÃI: - Ôi chao! Cô là ai mà hiểu nông nỗi làm người đến vậy!<br>(Nguyễn Trãi ở Đông Quan, Nguyễn Đình Thi)<br>Nhận định nào sau đây <b>phù hợp</b> <b>nhất</b> về ý nghĩa được gợi ra từ đoạn đối thoại trên?", "choices": ["Đoạn thoại khẳng định sự bất lực của con người trước lòng dạ khó lường và bản chất đa diện của xã hội thời loạn.", "Đoạn thoại thể hiện sự đối lập giữa lí trí từng trải và trực giác trong trẻo, suy tư về khả năng nắm bắt bản chất con người.", "Đoạn thoại nhằm đề cao phẩm chất ngây thơ như một cách duy nhất để nhìn thấu bản chất con người giữa thời biến động.", "Đoạn thoại phản ánh tâm thế hoài nghi của Nguyễn Trãi trước thực tại nhiễu nhương cũng sự bi quan về bản chất con người."], "correctIndex": 1, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Đọc văn bản sau và trả lời câu hỏi:<br><i>Có thân có của phải hay lo,</i><br><i>Noi học song trời phú tính cho.</i><br><i>Ngày vắng xem thông dăm bảy quyển,</i><br><i>Đêm thanh đọc suốt một hai pho.</i><br><i>Làm văn quan điểm bày hàng diệc,</i><br><i>Áo gấm vua ban bố tử cò.</i><br><i>Này mặt trạng nguyên sao có hổ,</i><br><i>Ai lấy con mình thời gả cho.</i><br><i>(Hoạ nhân sĩ vận, Nguyễn Bỉnh Khiêm)</i><br><b><i>Chú thích:</i></b><br>[1] Quan điểm: quan trường chấm thi và phê điểm; ý nói văn hay được khen ngợi nối tiếp nhau như đàn chim diệc bay thành hàng.<br>[2] Bố tử cò: áo thêu chim cò – phẩm phục của quan văn; trạng nguyên được ban áo mạo có thêu chim cò.<br>Đâu là cảm hứng chủ đạo của bài thơ trên?", "choices": ["Ca ngợi cuộc sống nhàn tản, thanh cao của người trí thức sau khi rời bỏ chốn quan trường.", "Thái độ phê phán, mỉa mai thói học hình thức và tâm lý sính danh lợi trong xã hội phong kiến.", "Thể hiện nỗi lo âu trước sự suy thoái của đạo học và giá trị truyền thống.", "Thái độ giáo huấn, nhấn mạnh vai trò việc chăm chỉ học hành đối với kẻ sĩ."], "correctIndex": 3, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<br><i>“...Chị nhiều hờn giận, yêu thương</i><br><i>Vầng trăng còn lấm mùi hương hẹn hò</i><br><i>Em chưa được thế bao giờ</i><br><i>Tiết trinh thương chị đánh lừa trái tim!</i><br><i>Em thành vợ của chàng Kim</i><br><i>Ngồi ru giọt máu tượng hình chị trao</i><br><i>Giấu đầy đêm nỗi khát khao</i><br><i>Kiều ơi, em đợi kiếp nào để yêu!”</i><br>(Tâm sự nàng Thuý Vân, Trương Nam Hương)<br>Đâu là nhận định đúng nhất về chủ thể trữ tình của đoạn trích trên?", "choices": ["Đây là chủ thể trữ tình trực tiếp, cơ sở xác định là đại từng xư hô “em”.", "Đây là chủ thể trữ tình nhập vai, tác giả đã hoá thân vào Thuý Kiếu để bộc lộ nỗi niềm.", "Đây là chủ thể trữ tình nhập vai, tác giả đã “nhập vai” vào Thuý Vân để bộc lộ nỗi niềm.", "Đây là chủ thể trữ tình ẩn, chủ thể quan sát nhân vật Thuý Vân tâm sự với chị mình."], "correctIndex": 2, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "“<i>Ông Bổng hỏi tôi: &quot;Nhà này ai chủ trì kinh tế?&quot; Tôi bảo: &quot;Vợ cháu&quot;. Ông Bổng bảo: &quot;Đấy là ngày thường. Tao hỏi đám ma này thì ai chủ trì kinh tế&quot;&quot; Tôi bảo: &quot;Vợ cháu&quot;. Ông Bổng bảo: &quot;Không được con ơi, khác máu tanh lòng. Tao bảo bố mày nhé&quot;. Tôi bảo: “Ông để con&quot;. Ông Bổng bảo: &quot;Đưa tao bốn nghìn, mày định làm bao nhiêu mâm?&quot; Tôi bảo: &quot;Mười mâm&quot;. Ông Bổng bảo: &quot;Không đủ cho đô tùy rửa ruột. Mày bàn với vợ mày đi. Bốn mươi mâm&quot;. Tôi đưa cho ông bốn nghìn rồi vào nhà. Vợ tôi bảo: “Em nghe hết rồi, em tính ba chục mâm, tám trăm đồng một mâm, ba tám hai tư. Hai tư nghìn, phụ phí sáu nghìn. Việc mua bán em lo. Cỗ giao cho cô Lài. Đừng nghe ông Bổng, lão ấy đểu lắm&quot;. Tôi bảo: &quot;ông Bổng cầm bốn nghìn rồi&quot;. Vợ tôi bảo: &quot;Buồn anh lắm&quot;. Tôi bảo: &quot;Anh đòi lại nhé&quot;. Vợ tôi bảo: &quot;Thôi, coi như trả công. Lão ấy tốt nhưng nghèo”.” </i><br>(Tướng về hưu, Nguyễn Huy Thiệp)<br>Nhận định nào sau đây thể hiện đúng và đầy đủ nhất đặc điểm các nhân vật trong đoạn trích?", "choices": ["Ông Bổng vừa chịu chi phối bởi tâm lí sĩ diện cộng đồng, vừa bộc lộ tính cơ hội; người vợ thực tế, tính toán rõ ràng; còn “tôi” thiếu bản lĩnh nên bị dẫn dắt bởi cả hai phía.", "Ông Bổng chỉ vì lợi ích cá nhân; người vợ thực dụng; còn “tôi” bị động và không có chính kiến riêng.", "Ông Bổng đại diện cho truyền thống cộng đồng; người vợ đại diện cho lối sống kinh tế mới; còn “tôi” là trung tâm dung hòa hai hệ giá trị.", "Ông Bổng nhiệt tình nhưng bảo thủ; người vợ khôn ngoan song lạnh lùng; còn “tôi” quyết đoán nhưng thiếu kinh nghiệm sống."], "correctIndex": 0, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<br><b>Phiên âm Hán Việt:</b><br>“Cổ lai danh lợi nhân,<br>Bôn tẩu lộ đồ trung.<br>Phong tiền tửu điếm hữu mỹ tửu,<br>Tỉnh giả thường thiểu, tuý giả đồng.<br>Trường sa, trường sa, nại cừ hà?”<br>(Sa hành đoản ca, Cao Bá Quát)<br><b>Bản dịch nghĩa</b><br>Xưa nay hạng người danh lợi,<br>Vẫn tất tả ở ngoài đường sá.<br>(Hễ) quán rượu ở đầu gió có rượu ngon,<br>(Thì) người tỉnh thường ít mà người say vô số.<br>Bãi cát dài, bãi cát dài, biết tính sao đây?<br>(Bài ca ngắn đi trên cát)<br>Cụm từ “tuý giả đồng” (người say vô số) trong bài thơ chỉ đối tượng nào?", "choices": ["Những người ham hưởng lạc, đắm chìm trong thú vui vật chất tầm thường của đời sống thường nhật.", "Những kẻ mưu cầu danh lợi, bị cuốn vào vòng xoáy công danh mà đánh mất sự tỉnh táo.", "Những người lữ khách mệt mỏi trên hành trình dài, tìm đến rượu như một cách giải tỏa nỗi nhọc nhằn.", "Những kẻ yếu đuối trước cám dỗ vật chất, không đủ bản lĩnh vượt qua thử thách cuộc đời."], "correctIndex": 1, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<br><i>“Nàng rằng: “Trộm liếc dung quang,</i><br><i>Chẳng sân ngọc bội thì phường Kim Môn.</i><br><i>Nghĩ mình phận mỏng cánh chuồn,</i><br><i>Khuôn xanh biết có vuông tròn mà hay?”</i><br>(Truyện Kiều, Nguyễn Du)<br>Từ “khuôn xanh” được hiểu chính xác nhất là gì?", "choices": ["Khuôn phép của lễ giáo phong kiến chi phối số phận người phụ nữ.", "Dư luận thế gian có khả năng định đoạt hạnh phúc cá nhân.", "Chuẩn mực xã hội về danh phận và địa vị trong hôn nhân.", "Tạo hóa, thế lực vô hình quyết định vận mệnh con người."], "correctIndex": 3, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<i>“Trăng bao nhiêu tuổi trăng già</i><br><i>Núi bao nhiêu tuổi gọi là núi non?” (Ca dao)</i><br>Biện pháp chơi chữ trong câu ca dao trên dựa trên hiện tượng nào?", "choices": ["Đồng âm", "Điệp âm", "Trại âm", "Nói lái"], "correctIndex": 0, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<i>“Khác với nhân vật “Thị Kính”, cô “Thị Mầu” lại biểu hiện cho một phẩm chất khác của người phụ nữ Việt Nam đó là: khát khao yêu đương. [...] Cô Thị Mầu trong chèo lại là một tấm gương điển hình về sự phá phách, chống lại những trói buộc của chế độ phong kiến hà khắc, khát khao hướng tới hạnh phúc của người phụ nữ thời bấy giờ.” </i>(Trích theo Nguyễn Quang Vinh (2010), “Thân phận người phụ nữ trong chèo cổ”, Tạp chí Ngày Nay, Liên hiệp các Hội UNESCO Việt Nam, ngày 11/3/2010)<br>Nhân vật “Thị Mầu” thuộc kiểu nhân vật nào trong chèo?", "choices": ["Đào thương", "Đào lệch", "Đào pha", "Mụ"], "correctIndex": 1, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": "<i>Việt Nam từ thời lập quốc với quốc hiệu Văn Lang - Âu Lạc (cách ngày nay khoảng 2.500 năm) đã là quốc gia đa tộc người. Các dấu hiệu văn hóa hiện tại còn nhận biết được qua các di vật khảo cổ học cho thấy, có thể cư dân của các quốc gia cổ đại ấy nói các ngôn ngữ khác nhau thuộc ngữ hệ Môn - Khmer cổ, Việt - Mường cổ, Tày - Thái cổ.</i><br><i>Cùng với việc mở rộng và củng cố cương vực của các triều đại phong kiến, thì tính đa tộc người của quốc gia Việt Nam càng trở nên rõ rệt hơn. Theo công bố chính thức của Nhà nước vào năm 1972, nước Việt Nam có 54 tộc người, thuộc nhiều nhóm ngôn ngữ - tộc người khác nhau: Việt - Mường, Môn - Khmer, Tày - Thái, Nam Đảo, Mông - Dao, Tạng - Miến, Hán, với những sắc thái văn hóa rất phong phú, đa dạng. Sắc thái văn hóa đa dạng ấy thể hiện trên ba cấp độ: nhóm ngôn ngữ - tộc người, tộc người và của nhóm địa phương.</i><br><i>Từ góc độ tộc người và văn hóa, Việt Nam giống như một Đông Nam Á thu nhỏ, bởi vì trên lãnh thổ Việt Nam hiện tồn tại đầy đủ các đại diện của các nhóm ngôn ngữ - tộc người (ngữ hệ và ngữ tộc) lớn của Đông Nam Á, như Nam Á (trong đó có Môn - Khmer, Việt - Mường, Thái, Mông - Dao), Nam Đảo (Austronesien) và Hán - Tạng (Tạng - Miến, Hán).</i><br><i>Từ các mối quan hệ tộc người, sự tương đồng về những đặc trưng văn hóa cũng thể hiện khá rõ. Mỗi tộc người thường hình thành các nhóm địa phương, giữa chúng có những khác biệt nhất định về thổ ngữ (phương ngữ), trang phục, phong tục tập quán, nghi lễ. Tình trạng đó khiến cho tính đa dạng và phong phú của văn hóa tộc người càng trở nên sống động và rõ rệt hơn.</i><br><i>Như vậy, xét từ góc độ nguồn gốc và lịch sử, Việt Nam là nơi hội tụ giữa các tộc người bản địa (Việt - Mường, Môn - Khmer) với các tộc từ phía bắc di cư xuống (Thái, Mông - Dao, Tạng - Miến, Hán) và từ biển phía nam lên (Nam Đảo). Tình trạng cư trú xen cài giữa các tộc người, một mặt, tạo môi trường thuận lợi cho sự giao lưu văn hóa; mặt khác, làm tách biệt giữa các nhóm địa phương của tộc người, góp phần làm suy giảm đáng kể tính thống nhất và cố kết văn hóa giữa các nhóm địa phương của tộc người, khiến bức tranh văn hóa càng trở nên phức tạp hơn.</i><br><i>Do lịch sử phân bố và di cư của các tộc người, ở Việt Nam đã hình thành nên các vùng sinh thái - tộc người khác nhau, như: Cư dân - tộc người đồng bằng và ven biển (Việt - Mường), cư dân - tộc người thung lũng (Tày - Thái), cư dân - tộc người rẻo núi giữa và cao nguyên (Môn - Khmer, Nam Đảo), cư dân - tộc người rẻo núi cao (Mông - Dao, Tạng - Miến). Chính nhân tố sinh thái tộc người này đã tạo nên những truyền thống văn hóa khác nhau, góp phần làm phong phú, đa dạng hơn văn hóa các tộc người Việt Nam.</i><br>(Ngô Đức Thịnh, <i>Đa dạng văn hóa và sự phát triển xã hội</i>. Tạp chí Cộng sản. 2018.)", "cauHoi": [{"question": "Trích đoạn in đậm trình bày thông tin theo cấu trúc nào?", "choices": ["Trật tự thời gian", "Nguyên nhân – kết quả", "Thông tin chính – thông tin chi tiết", "Đối tượng phân loại"], "correctIndex": 3, "explain": ""}, {"question": "Thông tin chính của văn bản là gì?", "choices": ["Trình bày đặc điểm đa tộc người và sự phong phú, đa dạng về ngôn ngữ – văn hóa của Việt Nam từ nguồn gốc lịch sử đến hiện tại.", "Khẳng định Việt Nam là quốc gia có lịch sử hình thành lâu đời với nền văn minh nông nghiệp đặc sắc.", "Chứng minh sự vượt trội của các nhóm ngôn ngữ – tộc người bản địa so với các nhóm di cư.", "Phân tích vai trò của yếu tố sinh thái trong việc hình thành bản sắc văn hóa thống nhất của các tộc người Việt Nam."], "correctIndex": 0, "explain": ""}, {"question": "Đâu là cách chia bố cục phù hợp nhất cho văn bản trên?", "choices": ["(1) Nguồn gốc đa tộc người thời cổ đại; (2) Thực trạng 54 tộc người hiện nay; (3) Hệ quả của sự giao lưu và phân bố sinh thái – tộc người.", "(1) Quá trình hình thành tính đa tộc người; (2) Đặc điểm cấu trúc ngôn ngữ – tộc người; (3) Ảnh hưởng của lịch sử di cư và sinh thái đến sự đa dạng văn hóa.", "(1) Giới thiệu quốc hiệu Văn Lang – Âu Lạc; (2) Phân loại các ngữ hệ ở Đông Nam Á; (3) Đánh giá sự phát triển kinh tế – xã hội Việt Nam.", "(1) Các nhóm ngôn ngữ cổ; (2) Các nhóm địa phương; (3) Sự suy giảm tính cố kết văn hóa trong thời hiện đại."], "correctIndex": 1, "explain": ""}, {"question": "Thông tin chi tiết nào cho thấy “Việt Nam giống như một Đông Nam Á thu nhỏ”?", "choices": ["Việt Nam có 54 tộc người với quy mô dân số và điều kiện sống khác nhau.", "Trên lãnh thổ Việt Nam tồn tại đầy đủ đại diện của các nhóm ngôn ngữ – tộc người lớn của Đông Nam Á.", "Các tộc người ở Việt Nam có sự đa dạng về trang phục, phong tục và nghi lễ truyền thống.", "Các triều đại phong kiến đã mở rộng và củng cố cương vực quốc gia qua nhiều thế kỉ."], "correctIndex": 1, "explain": ""}, {"question": "Đâu không phải là thông tin có trong văn bản?", "choices": ["Quá trình mở rộng và củng cố lãnh thổ dưới các triều đại phong kiến là nguyên nhân chính thúc đẩy tính chất đa dạng tộc người của Việt Nam.", "Việt Nam là điểm gặp gỡ của các tộc người bản địa và các dòng di cư từ bắc xuống, từ biển phía nam lên.", "Kết luận về việc cư dân cổ đại sử dụng các ngôn ngữ thuộc ngữ hệ Môn - Khmer, Việt - Mường và Tày - Thái được đưa ra trên cơ sở suy đoán khoa học từ các di vật khảo cổ học.", "Sự phân tán cư trú làm giảm tính thống nhất nội bộ tộc người và làm gia tăng tính phức tạp của bức tranh văn hóa."], "correctIndex": 0, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": "<i>(1) Khép lại cái nhìn nặng màu sắc chính trị hóa, lí tưởng hóa theo kiểu phân tuyến ta - địch, thắng – thua, chính nghĩa – phi nghĩa của văn học cách mạng, độ lùi thời gian cùng với những thay đổi trong sinh quyển văn hóa, xã hội giúp người viết lật trở, chiêm nghiệm chiến tranh từ lăng kính nhân văn, nhân bản gắn với những giá trị phổ quát của nhân loại. Chiến tranh hiện hình trên trang viết hôm nay chủ yếu từ cảm quan của nỗi buồn, của những suy tư, trăn trở trước quá khứ, hiện tại và cả tương lai của “mình” và “họ”. Con người, qua cuộc chiến, với đầy những bầm dập, thương tổn, những dư chấn nặng nề cả thể xác lẫn tâm hồn, vì thế “không một ai muốn mình sẽ tiếp tục là một con số cộng thêm trong phép thống kê xương máu” (Chiến tranh và phép thống kê - Bích Ngân). Hiện thực chiến tranh và hậu chiến đâu còn là “chiếc ráng chiều quá đẹp” như cách ví von của Nguyễn Minh Châu mà xám một màu buồn rợn bởi những đau thương, mất mát, những mảng sáng tối xô bồ khiến không ít quân nhân, thường nhân cả hai bên chiến tuyến – những người đã bị chiến tranh vô tình hay cố ý kéo vào – đều không khỏi bàng hoàng, suy sụp, thậm chí mất khả năng sống bình thường.</i><br><i>(2) Nỗ lực hiện đại hóa văn xuôi của đội ngũ nhà văn hôm nay thể hiện rõ nhất ở chỗ họ mạnh dạn đi vào những cạnh khía nhạy cảm của chiến tranh với cái nhìn trực diện, phản tỉnh. Đó là những trang viết lạ lẫm, đầy ám ảnh nhưng cũng nhiều mê hoặc về đề tài da cam (Tiếng lục lạc – Nguyễn Quang Lập, Mười ba bến nước – Sương Nguyệt Minh, Cơ bản là buồn – Nguyễn Ngọc Thuần,…). Hai cuộc chiến tranh biên giới cũng là hai thỏi nam châm xoáy hút tâm lực, bút lực của người viết. Hơn ba thập niên, nhất là khoảng thời gian gần 20 năm đầu thế kỉ XXI, xuất hiện hàng loạt tiểu thuyết viết về chiến tranh biên giới Tây Nam: Dòng sông của Xô Nét (Nguyễn Trí Huân), Chiến tranh không phải trò đùa (Khuất Quang Thụy), Dòng sông nước mắt (Thanh Giang), Biên giới, Bên rừng thốt nốt, Đất không đổi màu, Người đàn bà khóc mướn (Nguyễn Quốc Trung), Ngôi chùa ở Pratthana, Khoảng rừng có những ngôi sao (Văn Lê), Thế giới xô lệch (Bích Ngân), Bên dòng sông Mê (Bùi Thanh Minh), Miền hoang (Sương Nguyệt Minh), Hoang tâm (Nguyễn Đình Tú), Mùa xa nhà (Nguyễn Thành Nhân), Rừng đói (Nguyễn Trọng Luân), Chuyện Lính Tây Nam (Trung Sỹ), Mùa chinh chiến ấy (Đoàn Tuấn), Về từ hành tinh kí ức (Võ Diệu Thanh)…; chiến tranh biên giới phía Bắc: Xác phàm (Nguyễn Đình Tú), Mình và họ (Nguyễn Bình Phương),...</i><br><i>(3) Chiến tranh đã lùi xa, nhưng những nhà văn trải nghiệm nó, dù trực tiếp hay gián tiếp, cũng luôn cảm thấy mình mắc nợ những ân ưu ngày cũ. Dư âm, dư chấn của cuộc chiến cứ mãi đeo đẳng, khiến họ phải viết ra để nhớ lại, sống lại một thời gian khổ, bi tráng mà bản thân, bạn bè, dân tộc đã sống qua. Chuyện Lính Tây Nam được Trung Sỹ viết trong tâm thế vượt lên chính mình: trực diện nhìn lại cuộc chiến tranh trên đất Campuchia để soi rọi một thời bi hùng của thế hệ, đất nước mình, để đưa ra ánh sáng sự thật trần trụi của cái lò lửa địa ngục phi nhân ấy. Bằng cái nhìn của người trong cuộc, người đi qua ngoái lại, nhà văn đã khiến chúng ta kinh ngạc bởi hiện thực đa chiều, chân thực, tươi nguyên và sinh động đến rùng mình về một chiến trường K còn ít được biết đến trong văn học, khá xa lạ với độc giả trong và ngoài nước, vì thế có sức lay động lớn. Dù không gọi đích danh, nhưng lần đầu tiên trong văn học chính thống, quân xâm lược phương Bắc cũng đã được điểm mặt chỉ tên. Đó là bọn Khựa (Mình và họ), là giặc Khợ (Xác phàm). Cả hai cách gọi này đều cho thấy thái độ căm thù, khinh bỉ của tác giả trước hành động bất nhân, phi nghĩa của kẻ thù, đồng thời tạo một khoảng cách vừa đủ để hiện thực lịch sử với hiện thực văn chương soi chiếu lẫn nhau nhưng không trùng khít lên nhau. Dụng ý nghệ thuật đó giúp người viết tự do thể nghiệm, sáng tạo và tỏ bày những suy cảm về lịch sử, về nhân sinh, thế cuộc.</i><br>(Bùi Thanh Truyền (2020), “Động hình mới của văn xuôi chiến tranh qua những phác thảo rời”, Nghiên cứu Văn học, Số 1)", "cauHoi": [{"question": "Luận đề chính được triển khai trong văn bản trên là gì?", "choices": ["Khẳng định văn học cách mạng đã hoàn thành vai trò lịch sử và nhường chỗ cho các khuynh hướng sáng tác mới.", "Phân tích sự thay đổi của đề tài chiến tranh nhằm phản ánh sự phát triển của thị hiếu độc giả hiện đại.", "Chứng minh chiến tranh luôn là nguồn cảm hứng chủ đạo quyết định diện mạo văn học Việt Nam.", "Làm rõ sự chuyển biến trong cách nhìn và cách viết về chiến tranh của văn xuôi đương đại theo hướng đa chiều và nhân văn."], "correctIndex": 3, "explain": ""}, {"question": "Nội dung nào sau đây phản ánh đúng luận điểm trung tâm của đoạn (1)?", "choices": ["Văn học cách mạng đã xây dựng hình tượng chiến tranh mang tính sử thi, góp phần củng cố tinh thần dân tộc.", "Những tổn thất do chiến tranh gây ra khiến con người đánh mất niềm tin vào tương lai và các giá trị xã hội.", "Sự thay đổi bối cảnh lịch sử – xã hội giúp người viết nhìn lại chiến tranh từ góc độ nhân văn, nhấn mạnh vào sang chấn của con người hậu chiến.", "Văn xuôi hiện đại chủ yếu phản ánh chiến tranh thông qua hồi ức cá nhân của những người trực tiếp tham chiến."], "correctIndex": 2, "explain": ""}, {"question": "Đâu là nhận xét đúng nhất về ý nghĩa của việc liệt kê hàng loạt tác phẩm và tác giả trong đoạn (2) là gì?", "choices": ["Minh chứng cụ thể cho xu hướng đổi mới của văn xuôi chiến tranh đương đại.", "Cho thấy sự gia tăng số lượng tác phẩm viết về chiến tranh trong thời kì đổi mới.", "Nhấn mạnh vai trò của chiến tranh biên giới như đề tài trung tâm của văn học hiện nay.", "Thể hiện sự đánh giá cao của tác giả đối với các tác phẩm đạt giải thưởng văn học."], "correctIndex": 0, "explain": ""}, {"question": "Thái độ của người viết đối với các nhà văn và tác phẩm được nhắc đến trong đoạn (3) là gì?", "choices": ["Hoài nghi trước những cách tân có thể làm sai lệch hiện thực lịch sử.", "Trân trọng và đồng cảm với nỗ lực nhìn lại chiến tranh một cách chân thực, đa chiều và giàu tính nhân văn.", "Phê phán việc khai thác đề tài chiến tranh nhằm gây hiệu ứng cảm xúc cho độc giả.", "Trung lập, chỉ dừng lại ở việc mô tả hiện tượng văn học mà không bày tỏ quan điểm."], "correctIndex": 1, "explain": ""}, {"question": "Nhận định nào sau đây phù hợp với nội dung văn bản?", "choices": ["Văn xuôi chiến tranh đương đại chủ yếu tái hiện chiến tranh như một bản anh hùng ca nhằm khơi dậy tinh thần dân tộc.", "Các nhà văn hiện nay tránh đề cập trực tiếp đến kẻ thù để duy trì tính trung lập trong diễn ngôn văn học.", "Văn học chiến tranh ngày nay tập trung vào yếu tố huyền thoại nhằm giảm nhẹ tính bi kịch của hiện thực.", "Văn xuôi chiến tranh đương đại chuyển từ cảm hứng ngợi ca sang phản tỉnh, chú trọng số phận cá nhân và hậu quả chiến tranh."], "correctIndex": 3, "explain": ""}], "khongXaoTron": true}], "anh": [{"noiDungChung": null, "cauHoi": [{"question": "<i class=\"huong-dan-cau\">Mark the letter A, B, C, or D on your answer sheet to indicate the correct answer to each of the following questions.</i><br>After lengthy discussions, the board finally settled the proposal to merge the two companies.", "choices": ["down", "on.", "up", "in"], "correctIndex": 1, "explain": "<b>Câu 31. Chọn B</b><br>settle on + N = quyết định chọn sau khi cân nhắc<br>Câu: “the board finally settled ___ the proposal”<br>✔ B. <b>on</b> → đúng cụm động từ<br>A. down → settle down = ổn định<br>C. up → settle up = thanh toán<br>D. in → settle in = làm quen"}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "This solution is proving to be much what we initially anticipated.", "choices": ["the most efficient and cost-effective", "efficient and more cost-effective", "as efficient and cost-effective as", "more efficient and cost-effective than"], "correctIndex": 3, "explain": "<b>Câu 32. Chọn D. </b>much + comparative + than<br>✔ D. more efficient and cost-effective than<br>A. the most → so sánh nhất (không có mốc so sánh)<br>B. efficient and more → sai cấu trúc song song<br>C. as…as → so sánh bằng (không phù hợp với “much”)"}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "After months of development and market analysis, the company a new product line this February, with production already underway", "choices": ["has launched", "is likely to launch", "has been going to launch", "is going to launch"], "correctIndex": 0, "explain": "<b>Câu 33. Chọn A</b><br>“production already underway” → việc ra mắt đã xảy ra.<br>Công thức dùng Present Perfect: <b>S + has/have + V3</b><br>✔ A. has launched → đã ra mắt<br>B. is likely to launch → có khả năng sẽ ra mắt (chưa xảy ra)<br>C. has been going to launch → sai cấu trúc<br>D. is going to launch → dự định tương lai"}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "The rapid deforestation in the region is predicted to cause a severe threatening numerous species.", "choices": ["ecological imbalance", "ecological disbalance", "ecology imbalance", "ecological discproportion"], "correctIndex": 0, "explain": "Chọn A<br>Cần tính từ + danh từ<br>✔ ecological (adj) imbalance (n)<br> ecology imbalance → danh từ + danh từ (sai loại từ)<br> disbalance → từ này hiếm/không tự nhiên<br> discproportion → sai chính tả"}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "The survey revealed that _____ students had a clear understanding of the topic, suggesting the need for additional lessons.", "choices": ["a few", "few", "several", "many"], "correctIndex": 1, "explain": "<b>Câu 35. Chọn B (few)</b><br>Câu có ý: cần thêm bài học → nghĩa tiêu cực.<br>a few = một vài (tích cực)<br>few = rất ít (tiêu cực)<br>✔ few → phù hợp nghĩa<br> many/several → trái nghĩa"}], "khongXaoTron": true}, {"noiDungChung": "<b>Câu 36-40: </b>Mark the letter A, B, C, or D on your answer sheet to indicate the <b><u>wrong word</u></b> use/form to each of the following statement.", "cauHoi": [{"question": "<u><b>A</u></b> unexpected event <b><u>occurred</u></b> during <u>the </u><b><u>concert</u></b>, <b><u>causing</u></b> the audience to panic.", "choices": ["A.", "occurred", "the concert", "causing"], "correctIndex": 0, "explain": "Câu 36. Chọn A. An + nguyên âm<br><b>An unexpected event</b>"}, {"question": "<u><b>The number</u></b> of women <b><u>participating</u></b> in beauty contests <b><u>witness</u></b> an <b><u>increase</u></b> every year.", "choices": ["The number.", "participating", "witness", "increase"], "correctIndex": 2, "explain": "<b>Câu 37. Chọn C. </b>The number of + N(plural) + V(singular)<br>✔ <b>witnesses</b><br> witness (thiếu -es)"}, {"question": "The <b><u>doctors’s</u></b> recommendations <b><u>were</u></b> crucial in improving the <b><u>hospital’s</u></b> <b><u>quality</u></b><u> </u><b><u>of </u></b><u>service</u>.", "choices": ["doctors’s.", "were", "hospital’s.", "quality of service"], "correctIndex": 0, "explain": "<b>Câu 38. Chọn A</b><br><b>Sở hữu cách:</b> doctors’ (nhiều bác sĩ). Không có dạng doctors’s"}, {"question": "<u>Many of</u> the passengers <u>were</u> unsure about what to do with <u>its luggage</u> when the<br>announcement <u>was made</u>.", "choices": ["Many of.", "were.", "its luggage.", "was made."], "correctIndex": 2, "explain": "<b>Câu 39. Chọn C</b><br>“passengers” số nhiều → đại từ phải là <b>their</b>"}, {"question": "<u>The professor</u>, <u>who</u> I met last week <u>gave</u> an inspiring lecture <u>on</u> environmental<br>policy.", "choices": ["The professor.", "who.", "gave.", "on."], "correctIndex": 1, "explain": "<b>Câu 40. Chọn B</b><br><b>Quy tắc mệnh đề quan hệ:</b><br>who = chủ ngữ<br>whom = tân ngữ<br>“I met ___” → tân ngữ → <b>whom</b>"}], "khongXaoTron": true}, {"noiDungChung": "<b>Câu 41-45: </b>Which of the following best restates each of the given sentences?", "cauHoi": [{"question": "“We will go on a picnic as long as the weather is nice”", "choices": ["We’ll go on a picnic if the weather is nice.", "We had better go on a picnic unless the weather is nice.", "We’ll go on a picnic immediately the weather is good.", "The weather is nice when we go on a picnic."], "correctIndex": 0, "explain": "<b>Câu 41. Chọn A. </b>as long as = if"}, {"question": "“Where did you go last night?” John said.", "choices": ["John wanted to know where I went the night before.", "John asked me where I had gone the previous night.", "John asked me where I had gone the following night.", "John wanted to know where I went last night."], "correctIndex": 1, "explain": "<b>Câu 42. Chọn B</b><br><b>Reported speech:</b><br>Lùi thì: went → had gone<br>last night → the previous night"}, {"question": "The coffee is not strong. It can’t help me stay awake.", "choices": ["The coffee is very strong but it can’t help me stay awake.", "I am awake because the coffee is not strong.", "The coffee is not strong enough to help me stay awake.", "The coffee is very strong so that it can’t help me stay awake."], "correctIndex": 2, "explain": "<b>Câu 43. Chọn C</b><br><b>Công thức: </b>not + adj + enough + to V"}, {"question": "Because the demand for beer was very high last month, its price increased much.", "choices": ["It was not until last month that the demand for beer was very high.", "Last month, the price for beer didn’t increase despite the high demand.", "Although the demand for beer was high, its price increased much.", "The demand for beer was so high that its price increased much last month."], "correctIndex": 3, "explain": "<b>Câu 44. Chọn D</b><br><b>Cấu trúc: </b>so + adj + that + clause<br>A → đảo ngữ sai nghĩa<br> B → trái nghĩa<br> C → although = tương phản (không đúng quan hệ nguyên nhân-kết quả)"}, {"question": "“Would you like some coffee?” Jane asked.", "choices": ["Jane offered me some coffee.", "Jane asked me would I like some coffee.", "Jane forced me to drink more coffee.", "Jane asked me if I want more coffee."], "correctIndex": 0, "explain": "<b>Câu 45. Chọn A </b>Would you like…? = lời đề nghị<br>B → sai trật tự câu gián tiếp<br> C → sai nghĩa<br> D → sai thì (want → wanted)"}], "khongXaoTron": true}, {"noiDungChung": "<b>Câu 46-52: </b>Read the passage carefully<br><b>1.</b> The idea of making English a second language in Vietnam’s educational system has been gaining<br>traction recently. It is not a simple plan, but it holds immense potential. By exploring how this initiative could transform education, we can understand the benefits it might bring to the country.<br><b>2.</b> Integrating English as a second language goes beyond traditional language classes. It’s about<br>creating an environment where students engage with English in a variety of contexts. Schools can incorporate bilingual teaching methods, offering subjects like math and science in both Vietnamese<br>and English. This approach not only enhances language proficiency but also builds critical thinking<br>and global <b>competency</b> among students.<br><b>3.</b> Adopting English widely also addresses practical needs. Vietnam’s economy is increasingly integrated with global markets, and English proficiency is a gateway to better opportunities. From international business to academic research, being fluent in English equips young learners with the tools to succeed in a competitive world. <b>This initiative</b>, however, must be inclusive, ensuring students from rural areas have equal access to quality English education.<br><b>4.</b> Teachers play a pivotal role in this transformation. Like skilled artisans shaping masterpieces, educators need the right training and resources to deliver effective bilingual lessons. This includes professional development programs, access to teaching materials, and technological support. The goal is not merely to teach English but to make it a medium for students to explore diverse perspectives and ideas.<br><b>5. </b>Technology can be a powerful ally in this transition. Digital platforms, educational apps, and virtual classrooms can supplement traditional teaching methods. Students could interact with native speakers or participate in international projects, making English learning more dynamic and engaging. It’s about creating a bridge between Vietnam and the rest of the world.<br><b>6.</b> Challenges like resource disparities and curriculum adjustments may arise, but the potential benefits outweigh the obstacles. By embracing English as a second language, Vietnam’s educational system could become a beacon of innovation, preparing students to thrive in a globalized future. The vision is clear: empower the next generation to communicate, collaborate, and lead on a global stage.", "cauHoi": [{"question": "What is the passage mainly about?", "choices": ["The benefits of adopting English as a second language in Vietnam", "How English education improves the local economy of rural areas in Vietnam", "Global economic trends influencing Vietnam&#x27;s education system and its learners", "The role of technology in teaching English worldwide and in Vietnam in particular."], "correctIndex": 0, "explain": "<b>Câu 46. Chọn A. Bài nói xuyên suốt về lợi ích của việc dùng English như ngôn ngữ thứ hai.</b><br><b> B, D: chỉ nói 1 phần (kinh tế / công nghệ).</b><br><b> C: không phải chủ đề chính.</b>"}, {"question": "According to paragraph 2, what does the word &quot;<b>competency</b>&quot; refer to?", "choices": ["The capacity to translate between Vietnamese and English accurately", "The basic knowledge of grammar and vocabulary in English", "The ability to use English effectively in global and academic contexts", "The requirement to pass standardized English exams"], "correctIndex": 2, "explain": "<b>Câu 47. Chọn C</b><br>“global competency” = khả năng sử dụng hiệu quả trong môi trường quốc tế.<br>A: không nói dịch thuật.<br> B: không chỉ ngữ pháp cơ bản.<br> D: không nói thi cử."}, {"question": "In paragraph 3, what does the phrase “<b>this initiative</b>” refer to?", "choices": ["The integration of Vietnam’s economy with global markets.", "The adoption of English widely.", "Providing better opportunities for international business.", "Equipping young learners with competitive tools for success."], "correctIndex": 1, "explain": "<b>Câu 48. Chọn B</b><br>“This initiative” quay lại ý ngay trước đó: adopting English widely.<br>A, C, D: là hệ quả, không phải initiative."}, {"question": "In paragraph 4, why are teachers compared to skilled artisans?", "choices": ["They need creativity to craft bilingual lessons.", "They necessitate appropriate training and tools.", "They create masterpieces in academic research.", "They shape students&#x27; lives with limited resources."], "correctIndex": 1, "explain": "<b>Câu 49. Chọn B. </b>So sánh giáo viên với nghệ nhân → cần đào tạo và công cụ.<br>A: không nhấn mạnh sáng tạo.<br> C: không nói nghiên cứu.<br> D: không nói thiếu nguồn lực."}, {"question": "In paragraph 5, what is the role of technology in English education?", "choices": ["To replace traditional teaching methods entirely", "To offer dynamic and engaging learning opportunities", "To limit students&#x27; interaction with native speakers", "To focus on vocabulary over critical thinking"], "correctIndex": 1, "explain": "<b>Câu 50. Chọn B</b><br>Đoạn 5: công nghệ làm việc học dynamic, engaging."}, {"question": "In paragraph 6, which of the following is a challenge mentioned about adopting<br>English?", "choices": ["A lack of student interest in learning English", "Changes to the educational program", "The decline of the Vietnamese language in education", "The high cost of hiring foreign teachers"], "correctIndex": 1, "explain": "<b>Câu 51. Chọn B</b><br>Có nhắc “curriculum adjustments”."}, {"question": "What can be inferred from paragraph 6 about the adoption of English as a second<br>language?", "choices": ["It implies that English education will not require significant investments.", "It suggests that Vietnam may abandon Vietnamese as a primary language.", "It indicates that the process will only benefit certain regions of the country.", "It will improve students’ opportunities despite initial challenges."], "correctIndex": 3, "explain": "<b>Câu 52. Chọn D</b><br>“benefits outweigh obstacles” → dù khó nhưng lợi ích lớn."}], "khongXaoTron": true}, {"noiDungChung": "<b>Câu 53-60: </b>Read the passage carefully<br><b>1.</b> The rise in crimes committed by youngsters has become a pressing concern for societies<br>worldwide. Over the past few decades, juvenile delinquency has evolved from minor to more<br>serious offenses, reflecting deeper social and psychological challenges. Understanding the factors driving this trend is key to addressing its root causes and creating effective solutions.<br><b>2.</b> Many young offenders are influenced by challenging <b>circumstances</b> in their upbringing. Factors like broken families, lack of parental guidance, and exposure to violence can lead youngsters down a path of criminal behavior. Peer pressure also plays a significant role; adolescents seeking acceptance often engage in risky activities, including theft, vandalism, and even gang involvement. These behaviors not only harm their victims but also limit the offenders&#x27; opportunities for a better future.<br><b>3.</b> The impact of technology and social media cannot be overlooked. While digital platforms offer opportunities for learning and connection, <b>they</b> also expose youngsters to harmful influences, such as cyberbullying, scams, and extremist ideologies. Easy access to violent content and illegal activities online has normalized certain behaviors, blurring the line between right and wrong for impressionable minds.<br><b>4.</b> Addressing crimes among youngsters requires a <b>multi-faceted</b> approach. Schools play a pivotal role in shaping young minds, and implementing programs that teach conflict resolution, emotional intelligence, and the consequences of criminal behavior can make a difference. Similarly, community outreach initiatives, such as mentorship programs and recreational activities, can<br>provide positive outlets for at-risk youth.<br><b>5.</b> Parents and guardians must also be actively involved in guiding their children. Open communication, consistent discipline, and monitoring of online activities are essential in fostering a safe and nurturing environment. Moreover, authorities need to focus on rehabilitation rather than punishment. Offering education and job training to young offenders can help them reintegrate into society as responsible individuals.<br>6. While juvenile crime presents significant challenges, the issue is far from insurmountable. By fostering supportive communities and prioritizing prevention, society can provide youngsters with the tools they need to thrive. This approach not only reduces crime rates but also empowers the next generation to contribute positively to their communities, ensuring a safer and brighter future for all.", "cauHoi": [{"question": "The best title for the passage can be _____.", "choices": ["The Role of Technology in Juvenile Delinquency", "Understanding and Addressing Crimes Amongst Youngsters", "Peer Pressure: The Main Cause of Youth Offenses", "How Schools Can Prevent Juvenile Crime"], "correctIndex": 1, "explain": "<b>Câu 53. Chọn B</b><br>Bài gồm nguyên nhân + giải pháp → tiêu đề bao quát nhất."}, {"question": "In paragraph 2, the word &quot;<b>circumstances</b>&quot; refers to _______.", "choices": ["opportunities offered by schools", "conditions in a young person&#x27;s upbringing", "the pressure of modern technology", "social problems created by families"], "correctIndex": 1, "explain": "<b>Câu 54. Chọn B</b><br>“circumstances” = hoàn cảnh sống/nuôi dạy."}, {"question": "In paragraph 2, <b>peer pressure</b> is described as _______.", "choices": ["the only cause of youth crime", "a factor that leads to criminal behavior among adolescents", "something that prevents young people from committing crimes", "a result of exposure to violence in families."], "correctIndex": 1, "explain": "<b>Câu 55. Chọn B</b><br>Peer pressure là một yếu tố dẫn đến phạm tội."}, {"question": "In paragraph 3, the word &quot;they&quot; can be replaced by _______.", "choices": ["harmful influences", "digital platforms", "youngsters", "illegal activities online."], "correctIndex": 1, "explain": "<b>Câu 56. Chọn B </b>“they also expose youngsters…”<br>“They” = digital platforms (chủ ngữ số nhiều gần nhất).<br>A: harmful influences là tân ngữ phía sau.<br> C, D: không phù hợp ngữ pháp."}, {"question": "According to paragraph 3, it is NOT mentioned that _______.", "choices": ["technology has both positive and negative effects on youngsters", "online platforms can make certain criminal behaviors seem acceptable", "violent content is sometimes easily accessible to young people", "social media eliminates peer pressure"], "correctIndex": 3, "explain": "<b>Câu 57. Chọn D</b><br>Không có chỗ nào nói social media loại bỏ peer pressure.<br>✔ A, B, C đều được nhắc trong bài."}, {"question": "In paragraph 4, the term &quot;<b>multi-faceted approach</b>&quot; means _______.", "choices": ["a solution involving different strategies", "a focus on traditional teaching methods", "a way to prevent all crimes at once", "a method designed only for schools"], "correctIndex": 0, "explain": "<b>Câu 58. Chọn A</b><br>“multi-faceted” = nhiều mặt → nhiều chiến lược."}, {"question": "It can be inferred from paragraph 5 that parental involvement _______.", "choices": ["guarantees that children will avoid all criminal behavior", "is unnecessary in the era of technology", "is key to guiding children towards positive actions", "focuses only on monitoring online activities."], "correctIndex": 2, "explain": "<b>Câu 59. Chọn C</b><br>Đoạn 5 nhấn mạnh vai trò chủ động của cha mẹ."}, {"question": "From paragraph 6, it can be seen that _______.", "choices": ["punishment is the primary solution to reducing crimes among youngsters", "addressing juvenile crime requires preventive measures and supportive communities", "technology should be limited to prevent youth involvement in crime", "only schools have the responsibility to tackle issues of juvenile delinquency."], "correctIndex": 1, "explain": "<b>Câu 60. Chọn B</b><br>Đoạn cuối: cần prevention + supportive communities."}], "khongXaoTron": true}], "kh": [{"noiDungChung": "<b>MÔN HOÁ - Dựa vào thông tin dưới đây để trả lời các Câu từ 103 đến 105 </b><br>Áp suất hơi bão hòa của chất lỏng dễ bay hơi là áp suất hơi của nó khi tốc độ bay hơi của chất lỏng bằng tốc độ ngưng tụ của hơi ở nhiệt độ nhất định. Chất càng dễ bay hơi thì áp suất hơi bão hòa cao và khi nhiệt độ tăng, áp suất hơi bão hòa cũng tăng. Liên hệ giữa áp suất hơi bão hòa của dung dịch <img class=\"anh-de\" src=\"data/anh/l6/c9158dd38ab3fa2e.png\" alt=\"\" style=\"width:33px;height:27px;vertical-align:middle\"> và áp suất hơi bão hòa của dung môi tinh chất <img class=\"anh-de\" src=\"data/anh/l6/e620b882295cb93c.png\" alt=\"\" style=\"width:22px;height:25px;vertical-align:middle\"> như sau:<br>Trong đó <img class=\"anh-de\" src=\"data/anh/l6/0c1ce11dbd4f710f.png\" alt=\"\" style=\"width:18px;height:25px;vertical-align:middle\"> và <img class=\"anh-de\" src=\"data/anh/l6/f57898d260341c84.png\" alt=\"\" style=\"width:18px;height:25px;vertical-align:middle\"> lần lượt là số mol của dung môi A và chất tan<b> B.</b><br>Hòa tan 24 gam urea <img class=\"anh-de\" src=\"data/anh/l6/666e5c004d39f7d3.png\" alt=\"\" style=\"width:78px;height:27px;vertical-align:middle\"> vào 200 gam nước được dung dịch X. Biết urea là chất tan không bay hơi và khối lượng phân tử của urea là <img class=\"anh-de\" src=\"data/anh/l6/0ac919ae8fd19734.png\" alt=\"\" style=\"width:64px;height:22px;vertical-align:middle\">. Khối lượng phân tử của nước <img class=\"anh-de\" src=\"data/anh/l6/146987d53719422e.png\" alt=\"\" style=\"width:47px;height:27px;vertical-align:middle\"> là <img class=\"anh-de\" src=\"data/anh/l6/9dcf538cf5f152f0.png\" alt=\"\" style=\"width:64px;height:22px;vertical-align:middle\">. Áp suất hơi bão hòa của nước nguyên chất ở <img class=\"anh-de\" src=\"data/anh/l6/d26d0b1a745bccd4.png\" alt=\"\" style=\"width:38px;height:22px;vertical-align:middle\"> là <img class=\"anh-de\" src=\"data/anh/l6/701496b124433446.png\" alt=\"\" style=\"width:78px;height:22px;vertical-align:middle\">.", "cauHoi": [{"question": "Nhận xét nào sau đây <b>sai</b>?", "choices": ["Áp suất hơi bão hòa của dung dịch X thấp hơn <img class=\"anh-de\" src=\"data/anh/l6/353dcedb24a1072a.png\" alt=\"\" style=\"width:88px;height:22px;vertical-align:middle\">.", "Khi nhiệt độ tăng, áp suất hơi bão hòa của dung dịch X tăng.", "Khi tăng nồng độ urea thì áp suất hơi bão hòa của dung dịch tăng.", "Áp suất hơi bão hòa của nước luôn lớn hơn áp suất hơi bão hòa của dung dịch X."], "correctIndex": 2, "explain": "<b>Hướng dẫn giải: </b><br>Theo giả thuyết, ta suy ra được P<sup>0</sup><sub>A</sub> = 23,8.<br>Số mol urea = m/M = 24/60 = 0,4 mol<br>Số mol H<sub>2</sub>O = 200/18 = 100/9 mol<br>Thay vào công thức của đề, ta có <img class=\"anh-de\" src=\"data/anh/l6/16f09999382f719c.png\" alt=\"\" style=\"width:198px;height:43px;vertical-align:middle\">mmHg<br>\\(\\mathbf{\\Rightarrow}\\)<b> A đúng</b><br><b>B. Đúng, </b>giả thuyết đề bài<br><b><u>C.</u> Sai, </b>vì nồng độ urea tăng \\(\\approx\\) số mol urea (n<sub>B</sub>) tăng \\(\\Rightarrow\\) giá trị của biểu thức ở mẫu tăng \\(\\Rightarrow\\) P<sub>A</sub> giảm (áp suất hơi bão hòa của dung dịch giảm).<br><b>D. Đúng</b>"}, {"question": "Có bốn dung dịch <img class=\"anh-de\" src=\"data/anh/l6/ad8e8a6deac62001.png\" alt=\"\" style=\"width:69px;height:25px;vertical-align:middle\"> và <img class=\"anh-de\" src=\"data/anh/l6/830c08f84457c64c.png\" alt=\"\" style=\"width:23px;height:25px;vertical-align:middle\"> được điều chế bằng cách hòa tan cùng một khối lượng lần lượt các chất tan: saccharose <img class=\"anh-de\" src=\"data/anh/l6/1b057ba01f9d04d9.png\" alt=\"\" style=\"width:81px;height:27px;vertical-align:middle\">, maltose <img class=\"anh-de\" src=\"data/anh/l6/41f61fb8ad71f224.png\" alt=\"\" style=\"width:81px;height:27px;vertical-align:middle\">, glycerol <img class=\"anh-de\" src=\"data/anh/l6/7556d039e4cba92c.png\" alt=\"\" style=\"width:68px;height:27px;vertical-align:middle\"> và sorbitol <img class=\"anh-de\" src=\"data/anh/l6/64dcd8b59e44c0b8.png\" alt=\"\" style=\"width:74px;height:27px;vertical-align:middle\"> vào cùng một lượng nước. Gọi <img class=\"anh-de\" src=\"data/anh/l6/56a193385bb1f938.png\" alt=\"\" style=\"width:55px;height:25px;vertical-align:middle\"> và <img class=\"anh-de\" src=\"data/anh/l6/d34c83e69a62366b.png\" alt=\"\" style=\"width:18px;height:25px;vertical-align:middle\"> lần lượt là áp suất hơi bão hòa của các dung dịch <img class=\"anh-de\" src=\"data/anh/l6/65061045b5dfb4d3.png\" alt=\"\" style=\"width:69px;height:25px;vertical-align:middle\"> và <img class=\"anh-de\" src=\"data/anh/l6/830c08f84457c64c.png\" alt=\"\" style=\"width:23px;height:25px;vertical-align:middle\">. Hãy chọn nhận xét đúng về mối quan hệ giữa <img class=\"anh-de\" src=\"data/anh/l6/56a193385bb1f938.png\" alt=\"\" style=\"width:55px;height:25px;vertical-align:middle\"> và <img class=\"anh-de\" src=\"data/anh/l6/75b5238a231d2878.png\" alt=\"\" style=\"width:18px;height:25px;vertical-align:middle\">.", "choices": ["<img class=\"anh-de\" src=\"data/anh/l6/e9756569b5498915.png\" alt=\"\" style=\"width:104px;height:25px;vertical-align:middle\">.", "<img class=\"anh-de\" src=\"data/anh/l6/de7660a756b6a7cf.png\" alt=\"\" style=\"width:104px;height:25px;vertical-align:middle\">.", "<img class=\"anh-de\" src=\"data/anh/l6/172cfed2b52572e0.png\" alt=\"\" style=\"width:104px;height:25px;vertical-align:middle\">.", "<img class=\"anh-de\" src=\"data/anh/l6/d1868fd19de335c1.png\" alt=\"\" style=\"width:104px;height:25px;vertical-align:middle\">."], "correctIndex": 3, "explain": "<b>Hướng dẫn giải: </b><br>Phân tử khối (M) saccharose (X<sub>1</sub>) = maltose (X<sub>2</sub>) = 342 (g/mol) | glyxerol (X<sub>3</sub>)= 92 g/mol | sobitol (X<sub>4</sub>) = 182 g/mol<br>Theo giả thuyết đề bài, các dung dịch được lấy cùng 1 khối lượng, hay cùng giá trị m.<br>Mà số mol = m/M \\(\\Rightarrow\\) <b>M càng lớn</b> \\(\\Rightarrow\\) số mol càng nhỏ \\(\\Rightarrow\\) <b>P<sub>A</sub> càng lớn. </b><br>\\(\\Rightarrow\\) <b>P<sub>3</sub> &lt; P<sub>4</sub>&lt; P<sub>1 </sub>= P<sub>2</sub></b> \\(\\Rightarrow\\) <b>D đúng</b>"}, {"question": "Cần hòa tan bao nhiêu gam glucose <img class=\"anh-de\" src=\"data/anh/l6/c06b4c897ed54079.png\" alt=\"\" style=\"width:74px;height:27px;vertical-align:middle\"> vào 200 g nước để tạo thành dung dịch có áp suất hơi bão hòa bằng với áp suất hơi bão hòa của dung dịch X ? Glucose là chất tan không bay hơi và khối lượng phân tử là <img class=\"anh-de\" src=\"data/anh/l6/fdfb35e4106dd760.png\" alt=\"\" style=\"width:71px;height:22px;vertical-align:middle\">.", "choices": ["8 gam.", "24 gam.", "36 gam.", "72 gam."], "correctIndex": 3, "explain": "<b>Hướng dẫn giải: </b><br>Dung dịch X là urea \\(\\Rightarrow\\) để áp suất hơi bão hòa của dung dịch glucose = áp suất hơi bão hòa cùa dung dịch urea, với cùng lượng H<sub>2</sub>O không đổi \\(\\Rightarrow\\) số mol glucose = số mol urea = 0,4 mol<br>Khối lượng glucose (m) = n.M = 0,4. 180 = <b>72</b> (g/mol) \\(\\Rightarrow\\) <b>D đúng</b>"}], "khongXaoTron": true}, {"noiDungChung": "<b>MÔN LÝ - Dựa vào thông tin dưới đây để trả lời các Câu từ 106 đến 108 </b><br>Sóng điện từ lan truyền trong môi trường chân không với vận tốc c, đó cũng là vận tốc lớn nhất trong tự nhiên ( <img class=\"anh-de\" src=\"data/anh/l6/f077a5087ba03b62.png\" alt=\"\" style=\"width:94px;height:22px;vertical-align:middle\">). Bước sóng <img class=\"anh-de\" src=\"data/anh/l6/0d4f39d047e12072.png\" alt=\"\" style=\"width:15px;height:18px;vertical-align:middle\"> liên hệ với chu kì T và tần số f của sóng điện từ theo biểu thức <img class=\"anh-de\" src=\"data/anh/l6/03194ccdf25cf8b9.png\" alt=\"\" style=\"width:78px;height:45px;vertical-align:middle\">. Trong truyền thông bằng sóng điện từ, người ta chia các dải sóng điện từ theo bảng dưới đây.<br>•Sóng dài (30 KHz – 300 KHz): sóng dài phản xạ tốt các tầng điện li, có thể phản xạ nhiều lần nên bị tầng điện li hấp thụ mạnh vì vậy công suất truyền tải phải lớn. Sóng dài không bị ảnh hưởng bởi hiện tượng giao thoa, điều kiện truyền ổn định nên thường được dùng liên lạc trong các thành phố.<br>•Sóng trung (300 KHz – 3000 KHz): sóng này bị ảnh hưởng mạnh bởi hiện tượng giao thoa, thường dùng trong liên lạc ở thành phố lớn.<br>•Sóng ngắn (3000 KHz – 30 MHz): sóng ngắn bị mặt đất và các vật cản hấp thụ mạnh do có tần số cao, sóng ngắn có thể liên lạc đi rất xa.<br>•Sóng cực ngắn: sóng này không bị phản xạ ở tầng điện li mà sẽ đi xuyên qua nó để vào không gian vũ trụ. Sóng này thường dùng trong phát thanh FM, phát truyền hình, liên lạc vũ trụ.", "cauHoi": [{"question": "Sóng điện từ có tần số 99 MHz thuộc loại", "choices": ["Sóng dài.", "Sóng trung.", "Sóng ngắn.", "Sóng cực ngắn."], "correctIndex": 2, "explain": "<b><u>Hướng dẫn giải</u></b><br><img class=\"anh-de\" src=\"data/anh/l6/afa4a7332bfaf412.png\" alt=\"\" style=\"width:84px;height:22px;vertical-align:middle\">nằm trong vùng <img class=\"anh-de\" src=\"data/anh/l6/74f1defee99011ff.png\" alt=\"\" style=\"width:121px;height:25px;vertical-align:middle\"> Sóng ngắn ⇒ <b>Đáp án C. </b>"}, {"question": "Để truyền tín hiệu từ Trái Đất lên tàu vũ trụ ngoài không gian mà <b>không bị tầng điện li phản xạ ngược trở lại</b>, cần chọn sóng có đặc điểm:", "choices": ["Bước sóng rất lớn", "Tần số nhỏ", "Tần số rất cao", "Phản xạ mạnh ở tầng điện li"], "correctIndex": 2, "explain": "<b>Đáp án:</b> <b>C. </b>Vì sóng cực ngắn có tần số rất cao, không bị phản xạ ở tầng điện li nên xuyên ra ngoài không gian."}, {"question": "Một tàu khảo sát đo độ sâu vùng biển bằng cách phát một xung sóng điện từ thẳng đứng xuống đáy biển. Sau <img class=\"anh-de\" src=\"data/anh/l6/2db9f8b67dc78113.png\" alt=\"\" style=\"width:56px;height:25px;vertical-align:middle\">, tàu thu được tín hiệu phản xạ trở lại. Biết vận tốc truyền sóng điện từ trong nước biển coi xấp xỉ bằng trong chân không:<br><img class=\"anh-de\" src=\"data/anh/l6/f5a75786b66a31e6.png\" alt=\"\" style=\"width:94px;height:25px;vertical-align:middle\">. Biết sóng có tần số <img class=\"anh-de\" src=\"data/anh/l6/42eb52b36bb6431b.png\" alt=\"\" style=\"width:88px;height:25px;vertical-align:middle\">. Loại sóng mà tàu đang sử dụng là:", "choices": ["Sóng cực ngắn", "Sóng ngắn", "Sóng trung", "Sóng dài"], "correctIndex": 3, "explain": "<b><u>Hướng dẫn giải</u></b><br>Thời gian là <b>cả đi và về</b>, nên: <img class=\"anh-de\" src=\"data/anh/l6/41f1eea116f8ecf5.png\" alt=\"\" style=\"width:160px;height:45px;vertical-align:middle\"><br>Độ sâu: <img class=\"anh-de\" src=\"data/anh/l6/14cbe9c10826ffbf.png\" alt=\"\" style=\"width:205px;height:25px;vertical-align:middle\"><br>Tần số: <img class=\"anh-de\" src=\"data/anh/l6/49076001af7da9db.png\" alt=\"\" style=\"width:88px;height:25px;vertical-align:middle\"><br>Bước sóng: <img class=\"anh-de\" src=\"data/anh/l6/2716003e6f60ff3e.png\" alt=\"\" style=\"width:163px;height:47px;vertical-align:middle\"> (vì<img class=\"anh-de\" src=\"data/anh/l6/e443dba7c3ff9cb0.png\" alt=\"\" style=\"width:67px;height:25px;vertical-align:middle\">) ⇒ <b>Đáp án</b> <b>D. Sóng dài</b>"}], "khongXaoTron": true}, {"noiDungChung": "<b>MÔN SINH - Dựa vào thông tin dưới đây để trả lời các Câu từ 109 đến 111</b><br>Một chu kì tim gồm ba pha: pha nhĩ co (pha co tâm nhĩ), pha thất co (pha co tâm thất) và dãn chung. Bảng dưới đây hiển thị một số thông số tại các thời điểm khác nhau trong chu kì tim. Thời gian của các thời điểm không theo đúng trình tự.<br><table class=\"bang-de\"><tr><td><b>Thời điểm trong chu kì tim</b></td><td><b>Áp lực tâm thất (kPa)</b></td><td><b>Thể tích máu trong tâm thất (cm<sup>3</sup>)</b></td><td><b>Van nhĩ thất</b></td><td><b>Van động mạch</b></td></tr><tr><td>A</td><td>2.0</td><td>70</td><td>Mở</td><td>Đóng</td></tr><tr><td>B</td><td>12.0</td><td>105</td><td>Đóng</td><td>Mở</td></tr><tr><td>C</td><td>1.5</td><td>125</td><td>Mở</td><td>Đóng</td></tr><tr><td>D</td><td>14.0</td><td>80</td><td>Đóng</td><td>Mở</td></tr></table>", "cauHoi": [{"question": "Biết máu từ tim chảy vào động mạch khi van động mạch mở (tức là pha tâm thất co, áp lực tâm thất lớn).<b> </b>Máu từ tim chảy vào động mạch vào thời điểm nào?", "choices": ["Chỉ thời điểm#A.", "Chỉ thời điểm B.", "Thời điểm A và C.", "Thời điểm B và D."], "correctIndex": 3, "explain": "<b><u>Hướng dẫn giải</u></b><br><i>Máu sẽ được đưa vào tâm thất phải thỏa đủ hai điều kiện là áp lực máu tại tâm thất phải cao và làm mở van động mạch. Tại thời điểm A và C áp lực máu quá thấp, không làm mở van động mạch nên máu không thể chảy vào động mạch</i>"}, {"question": "Nếu bắt đầu với thời điểm A, các thời điểm còn lại được sắp xếp theo thứ tự lần lượt là", "choices": ["B - C - D.", "C - B - D.", "C - D - B.", "D - C - B."], "correctIndex": 1, "explain": "<b><u>Hướng dẫn giải</u></b><br><i>Tại thời điểm A, van nhĩ thất đang mở =&gt; tâm thất giãn =&gt;áp lực thất thấp =&gt; sau đó tâm thất tiếp tục giãn =&gt; áp lực tiếp tục giảm, đồng thời máu từ nhĩ xuống thất =&gt; tăng thể tích máu trong tâm thất ( thời điểm C) =&gt; sau đó thất bắt đầu co khi thể tích trong máu được chứa trong thất đạt tối đa =&gt; tăng áp lực thất (thời điểm B) =&gt; sau đó thất tiếp tục co =&gt; tăng áp lực tâm thất làm mở van động mạch =&gt; máu được tống từ tâm thất lên động mạch chủ =&gt; giảm thể tích máu trong thất (thời điểm D).</i>"}, {"question": "Máu rời tâm nhĩ đạt thể tích lớn nhất vào thời điểm nào?", "choices": ["A.", "B.", "C", "D."], "correctIndex": 2, "explain": "<b><u>Hướng dẫn giải</u></b><br><i>Máu rời tâm nhĩ vào thời điểm B khi áp lực tâm thất giảm tối thiểu, đồng thời tâm nhĩ sẽ co bóp đẩy máu là mở van nhĩ thất và đi vào tâm thất =&gt; thể tích máu trong tâm thất tăng tối đa ở 125ml với áp lực thấp nhất là 1.5 kPa tại thời điểm C, chứng tỏ thể tích máu rời tâm nhĩ ở thời điểm này là cao nhất.</i>"}], "khongXaoTron": true}, {"noiDungChung": "<b>MÔN ĐỊA - Dựa vào thông tin dưới đây để trả lời các Câu từ 112 đến 114 </b><br>Kỷ lục về xuất khẩu gạo trong năm 2023 khi khối lượng và giá trị đều đạt đỉnh, 8,2 triệu tấn và 4,78 tỷ USD, tăng tương ứng <img class=\"anh-de\" src=\"data/anh/l6/cab0b112136b0562.png\" alt=\"\" style=\"width:47px;height:22px;vertical-align:middle\"> và <img class=\"anh-de\" src=\"data/anh/l6/bea378cb575cca04.png\" alt=\"\" style=\"width:48px;height:22px;vertical-align:middle\"> so với năm 2022. Thị trường số 1 của Việt Nam tiếp tục là Philippines, hiện chiếm khoảng <img class=\"anh-de\" src=\"data/anh/l6/5d540a74fcc229af.png\" alt=\"\" style=\"width:33px;height:18px;vertical-align:middle\"> thị phần gạo Việt Nam xuất khẩu. Trong năm 2023, lượng gạo xuất khẩu sang quốc gia này đạt 2,86 triệu tấn, tương ứng 1,54 tỷ USD. Xếp sau là Indonesia, Trung Quốc và các quốc gia châu Phi.<br>Sản lượng gạo thu hoạch lập kỷ lục mới, qua đó vừa đảm bảo nhu cầu trong nước, vừa đáp ứng lượng gạo xuất khẩu kỷ lục lần đầu vượt qua 8 triệu tấn. Một trong những điểm nổi bật là tỷ trọng các giống lúa thơm, lúa đặc sản hiện chiếm phần lớn. Cụ thể, giống Đài Thơm 8/OM18 chiếm <img class=\"anh-de\" src=\"data/anh/l6/2592cf4875ade817.png\" alt=\"\" style=\"width:35px;height:18px;vertical-align:middle\">, giống OM5451 chiếm khoảng 19%, giống ST (21/24/25) chiếm khoảng <img class=\"anh-de\" src=\"data/anh/l6/30d5967098bba546.png\" alt=\"\" style=\"width:25px;height:18px;vertical-align:middle\">.<br>Gạo Việt Nam được vinh danh là gạo ngon nhất thế giới tại Hội nghị lúa gạo quốc tế 2023 tổ chức tại Cebu - Philippines từ ngày 28 đến 30/11/2023...<br>Hạt gạo Việt Nam trở thành thương hiệu trên thương trường quốc tế như hiện nay nhờ công sức của tất cả các thành phần trong chuỗi ngành hàng lúa gạo. Ngành lúa gạo truyền đi thông điệp chúng ta có nhiều hiệp hội cùng hoạt động, nhưng không hiệp hội nào phủ định hiệp hội nào mà cùng ngồi lại với nhau, hội tụ những điểm chung, phát huy những điểm riêng là thế mạnh đê làm tốt hơn...<br>(Nguôn: https://vneconomy.vn/lua-gao-viet-nam-rang-danh-toan-the-gioi.htm)", "cauHoi": [{"question": "Thị trường số 1 của Việt Nam trong xuất khẩu lúa gạo là", "choices": ["Indonesia", "Lào", "Malaysia", "Philippines"], "correctIndex": 3, "explain": ""}, {"question": "Tỉ trọng giá trị xuất khẩu được tính bằng:", "choices": ["Giá trị xuất khẩu: Giá trị nhập khẩu x 100", "Giá trị nhập khẩu: Giá trị xuất khẩu <img class=\"anh-de\" src=\"data/anh/l6/038e1eb45a7fcea0.png\" alt=\"\" style=\"width:38px;height:18px;vertical-align:middle\">", "Giá trị xuất khẩu: Tổng giá trị xuất nhập khẩu x 100", "Giá trị nhập khẩu: Tổng giá trị xuất nhập khẩu <img class=\"anh-de\" src=\"data/anh/l6/152cb0e08e53374f.png\" alt=\"\" style=\"width:38px;height:18px;vertical-align:middle\">"], "correctIndex": 2, "explain": ""}, {"question": "Vùng có sản lượng lúa lớn nhất nước ta là", "choices": ["Đồng bằng sông Cửu Long.", "Đông Nam Bộ.", "Bắc Trung Bộ.", "Đồng bằng sông Hồng."], "correctIndex": 0, "explain": "<i class=\"canh-bao-lg\">(Lưu ý: lời giải gốc ghi đáp án D, còn đáp án tô trong đề là A — web đang dùng A.)</i><br><b><u>Hướng dẫn giải</u></b><br><b>112. Chọn D</b><br>Theo đoạn thông tin: &quot;Thị trường số 1 của Việt Nam tiếp tục là Philippines, hiện chiếm khoảng 35% thị phần gao Việt Nam xuất khẩu.&quot;<br><b>113. Chọn C</b><br>Tỉ trọng giá trị xuất khẩu trong tổng kim ngạch xuất nhập khẩu được tính theo công thức:<br>\\[\\text{Tỉ trọng xuất khẩu~} = \\frac{\\text{~Giá trị xuất khẩu~}}{\\text{~Tổng giá trị xuất nhập khẩu~}} \\times 100\\%\\]<br>⇒ Phù hợp với phương án Giá trị xuất khảu: Tổng giá trị xuất nhập khẩu\\(\\times 100\\).<br><b>114. Chọn A</b><br>Vùng có sản lượng lúa lớn nhất nước ta là Đồng bằng sông Cửu Long vì:<br>•Là vùng trọng điểm sản xuất lúa lớn nhất cả nước.<br>•Điêu kiện tự nhiên thuận lợi: đất phù sa màu mõ, khí hậu nóng ẳm, nguồn nước dồi dào.<br>•Là vùng đóng góp chử yếu cho xuất khẳu gạo của Việt Nam."}], "khongXaoTron": true}, {"noiDungChung": "<b>MÔN SỬ - Dựa vào thông tin dưới đây để trả lời các Câu từ 115 đến 117</b><br>Chiến dịch Việt Bắc thu - đông năm 1947 diễn ra từ tháng 10 đến tháng 12-1947, khi quân Pháp mở cuộc tiến công lên căn cứ địa Việt Bắc nhằm tiêu diệt cơ quan đầu não kháng chiến của Việt Nam. Quân và dân Việt Nam chủ động phản công (từ ngày 07-10 đến ngày 19-12-1947), bẻ gãy cuộc tiến công của quân Pháp, đẩy lùi quân Pháp ở một số vị trí như: Chợ Đồn, Chợ Rã, Đoan Hùng, Khe Lau... làm phá sản hoàn toàn kế hoạch “đánh nhanh, thắng nhanh” của thực dân Pháp, bảo vệ vững chắc căn cứ địa Việt Bắc.<br>Thu - đông 1950, quân đội nhân dân Việt Nam lần đầu tiên chủ động mở chiến dịch Biên giới (từ ngày 16-9 đến ngày 22-10-1950) nhằm tiêu diệt một bộ phận sinh lực địch, khai thông biên giới Việt - Trung, mở rộng và củng cố căn cứ địa Việt Bắc. Sau hơn một tháng chiến đấu, quân đội Việt Nam đã giải phóng một vùng rộng lớn dọc biên giới Việt - Trung, chọc thủng hành lang Đông - Tây, làm phá sản kế hoạch Rơ-ve của thực dân Pháp. Từ đây, quân đội Việt Nam giành được thế chủ động chiến lược trên chiến trường chính Bắc Bộ.<br><i>(Nguồn: Sách Lịch sử 12, Bộ Chân trời sáng tạo, trang 40-41)</i>", "cauHoi": [{"question": "Trong Chiến dịch Việt Bắc thu - đông năm 1947, quân và dân Việt Nam đã bẻ gãy cuộc tiến công của thực dân Pháp tại những địa điểm nào sau đây?", "choices": ["Chợ Đồn, Chợ Rã, Đoan Hùng, Khe Lau.", "Đông Khê, Thất Khê, Cao Bằng, Lạng Sơn.", "Hòa Bình, Sông Lô, Phú Thọ, Yên Bái.", "Điện Biên Phủ, Tuần Giáo, Lai Châu, Sơn La."], "correctIndex": 2, "explain": ""}, {"question": "Thắng lợi của Chiến dịch Việt Bắc thu - đông năm 1947 có ý nghĩa chủ yếu nào sau đây?", "choices": ["Buộc thực dân Pháp phải công nhận nền độc lập của Việt Nam.", "Làm phá sản hoàn toàn kế hoạch “đánh nhanh, thắng nhanh” của thực dân Pháp.", "Giành quyền chủ động chiến lược trên chiến trường chính Bắc Bộ.", "Mở rộng và củng cố căn cứ địa Việt Bắc."], "correctIndex": 1, "explain": ""}, {"question": "So với Chiến dịch Việt Bắc thu - đông năm 1947, điểm mới nổi bật của Chiến dịch Biên giới thu - đông năm 1950 được thể hiện ở nội dung nào sau đây?", "choices": ["Quân và dân Việt Nam chủ yếu đánh bại các cuộc tiến công quy mô lớn của địch.", "Ta lần đầu tiên giành thắng lợi quyết định trong chiến tranh chính quy.", "Quân đội Việt Nam chủ động mở chiến dịch tiến công và giành thế chủ động chiến lược.", "Cuộc kháng chiến chuyển từ phòng ngự sang phản công trên phạm vi cả nước."], "correctIndex": 2, "explain": "<b><u>Hướng dẫn giải</u></b><br><b>115.Chọn câu<u> A.</u></b><br><b>Giải thích: </b>Dòng 3-4-5 của đoạn tư liệu có nêu «Quân và dân Việt Nam chủ động phản công (từ ngày 07-10 đến ngày 19-12-1947), bẻ gãy cuộc tiến công của quân Pháp, đẩy lùi quân Pháp ở một số vị trí như: Chợ Đồn, Chợ Rã, Đoan Hùng, Khe Lau...»<br><b>116.Chọn câu <u>B.</u></b><br><b>Giải thích: </b>Đoạn tư liệu nêu rõ:<br>- Thực dân Pháp mở cuộc tiến công lên căn cứ địa Việt Bắc nhằm tiêu diệt cơ quan đầu não kháng chiến, nhanh chóng kết thúc chiến tranh.<br>- Quân và dân Việt Nam chủ động phản công, bẻ gãy cuộc tiến công của Pháp tại nhiều địa điểm quan trọng.<br>- Kết quả là “làm phá sản hoàn toàn kế hoạch ‘đánh nhanh, thắng nhanh’ của thực dân Pháp”, đồng thời bảo vệ vững chắc căn cứ địa Việt Bắc.<br>Phương án B trực tiếp phản ánh đúng ý nghĩa chủ yếu, nổi bật nhất của thắng lợi Chiến dịch Việt Bắc thu - đông 1947.<br><b>Các phương án khác không đúng vì:</b><br><b>- A: </b>Pháp không công nhận nền độc lập của Việt Nam sau chiến dịch này.<br><b>- C: </b>Giành thế chủ động chiến lược là kết quả của Chiến dịch Biên giới 1950, không phải Việt Bắc 1947.<br><b>- D: </b>Mở rộng, củng cố căn cứ địa Việt Bắc là mục tiêu và kết quả nổi bật của Chiến dịch Biên giới 1950.<br><b>117.Chọn câu</b> <b><u>C.</u></b><br><b>Giải thích: </b>So sánh hai chiến dịch trong tư liệu:<br>-Chiến dịch Việt Bắc 1947: ta ở thế phòng ngự - phản công (phản công chiến lược), đánh bại cuộc tiến công lớn của Pháp.<br>-Chiến dịch Biên giới 1950: ta lần đầu tiên chủ động mở chiến dịch tiến công quy mô lớn, có sự chuẩn bị đầy đủ về lực lượng và hậu phương.<br><b>Tư liệu khẳng định: </b>Sau thắng lợi Chiến dịch Biên giới, ta “giành được thế chủ động chiến lược trên chiến trường chính Bắc Bộ”.<br>Vì vậy, phương án C khái quát đúng điểm mới nổi bật và có tính bước ngoặt của Chiến dịch Biên giới 1950 so với Việt Bắc 1947.<br><b>Các phương án khác không đúng vì:</b><br><b>- A: </b>Nội dung này phù hợp với Việt Bắc 1947 hơn.<br><b>- B: </b>Ta chưa giành thắng lợi quyết định kết thúc chiến tranh năm 1950.<br><b>- D: </b>Kháng chiến chưa chuyển sang phản công trên phạm vi cả nước."}], "khongXaoTron": true}, {"noiDungChung": "<b>MÔN KTPL - Dựa vào thông tin dưới đây để trả lời các Câu từ 118 đến 120 </b><br>Hiện nay, quy mô dân số Việt Nam năm 2023 đạt 100,3 triệu người, lực lượng lao động từ 15 tuổi trở lên là 52,4 triệu người, trong đó khu vực thành thị chiếm 19,5 triệu người ( <img class=\"anh-de\" src=\"data/anh/l6/319725d35554103c.png\" alt=\"\" style=\"width:48px;height:22px;vertical-align:middle\">) và khu vực nông thôn chiếm 32,9 triệu người ( <img class=\"anh-de\" src=\"data/anh/l6/179adcfe2a5bcde4.png\" alt=\"\" style=\"width:48px;height:22px;vertical-align:middle\">). Lao động nam là 27,9 triệu người ( <img class=\"anh-de\" src=\"data/anh/l6/088c3dd3fe70fbf7.png\" alt=\"\" style=\"width:47px;height:22px;vertical-align:middle\">) và lao động nữ là 24,5 triệu người <img class=\"anh-de\" src=\"data/anh/l6/dff76b66d87b79da.png\" alt=\"\" style=\"width:58px;height:22px;vertical-align:middle\">. Tỷ lệ tham gia lực lượng lao động đạt <img class=\"anh-de\" src=\"data/anh/l6/ed1155ac797b780b.png\" alt=\"\" style=\"width:47px;height:22px;vertical-align:middle\">, trong đó nam giới là <img class=\"anh-de\" src=\"data/anh/l6/a22ceacc012721fa.png\" alt=\"\" style=\"width:48px;height:22px;vertical-align:middle\"> và nữ giới là <img class=\"anh-de\" src=\"data/anh/l6/d54782acd6d25da7.png\" alt=\"\" style=\"width:63px;height:22px;vertical-align:middle\">. Việt Nam đang trong giai đoạn cơ cấu dân số vàng, với <img class=\"anh-de\" src=\"data/anh/l6/d453167d97a22e81.png\" alt=\"\" style=\"width:48px;height:22px;vertical-align:middle\"> dân số trong độ tuổi 15-59. Tỷ lệ lao động qua đào tạo tăng từ <img class=\"anh-de\" src=\"data/anh/l6/1a9bf497c1de8dd0.png\" alt=\"\" style=\"width:35px;height:18px;vertical-align:middle\"> (2010) lên 65\\% (2020), trong đó năm 2023 có 14,1 triệu người ( <img class=\"anh-de\" src=\"data/anh/l6/65515aba8939a048.png\" alt=\"\" style=\"width:35px;height:18px;vertical-align:middle\"> dân số) được đào tạo có bằng cấp hoặc chứng chỉ. Chỉ số vốn nhân lực (HCI) tăng từ 0,66 (2010) lên 0,69 (2020), và chỉ số phát triển con người (HDI) tăng từ 0,475 (1990) lên 0,704 (2019), đưa Việt Nam vào nhóm quốc gia phát triển con người cao.<br>Lực lượng lao động Việt Nam ngày càng cải thiện về chất lượng, đóng góp quan trọng trong các lĩnh vực như công nghệ thông tin, y tế, giáo dục, sản xuất ô tô và công nghiệp năng lượng... Tuy nhiên, để đáp ứng yêu cầu đẩy mạnh CNH, HĐH toàn diện và đồng bộ, phát triển kinh tế số và kinh tế tri thức, nguồn nhân lực Việt Nam hiện vẫn còn nhiều hạn chế cần chú trọng tiếp tục nâng cao trình độ chuyên môn và kỹ năng để tận dụng tối đa thời kỳ dân số vàng và đáp ứng yêu càu hội nhập quốc tế.<br>(Nguồn: Tạp chí điện tử Lý luận chính trị 15/08/2024)", "cauHoi": [{"question": "Dựa trên thông tin, đặc điểm nào sau đây phản ánh đúng cơ cấu lao động Việt Nam năm 2023?", "choices": ["Khu vực nông thôn chiếm <img class=\"anh-de\" src=\"data/anh/l6/6136c6b402ac6360.png\" alt=\"\" style=\"width:48px;height:22px;vertical-align:middle\"> lực lượng lao động và lao động nữ vượt trội về số lượng so với lao động nam.", "Lực lượng lao động ở thành thị chiếm <img class=\"anh-de\" src=\"data/anh/l6/ad533673ab4123c9.png\" alt=\"\" style=\"width:48px;height:22px;vertical-align:middle\">, trong khi khu vực nông thôn chiếm tỷ trọng lớn hơn và lao động nam chiếm đa số.", "Lao động nam và nữ tham gia lực lượng lao động với tỷ lệ tương đương nhau, đặc biệt ở khu vực nông thôn.", "Việt Nam đã đạt được sự cân bằng giữa lao động thành thị và nông thôn trong cơ cấu lao động tổng thể."], "correctIndex": 1, "explain": ""}, {"question": "Dựa trên thông tin, sự gia tăng tỷ lệ lao động qua đào tạo từ <img class=\"anh-de\" src=\"data/anh/l6/c0f6b0dbe02bf725.png\" alt=\"\" style=\"width:35px;height:18px;vertical-align:middle\"> (2010) lên <img class=\"anh-de\" src=\"data/anh/l6/9853114fba56481f.png\" alt=\"\" style=\"width:35px;height:18px;vertical-align:middle\"> (2020) và các chỉ số HCI, HDI phản ánh điều gì về chất lượng nguồn nhân lực Việt Nam?", "choices": ["Việt Nam đã đạt được sự phát triển đồng đều về chất lượng nguồn nhân lực giữa khu vực thành thị và nông thôn.", "Sự cải thiện chất lượng lao động chủ yếu nhờ vào việc tăng tỷ lệ tham gia lao động của nữ giới.", "Chất lượng nguồn nhân lực phát triển mạnh ở khu vực thành thị, nơi có tỷ lệ đào tạo và cơ hội việc làm vượt trội hơn so với nông thôn.", "Chỉ số HCI tăng cao chủ yếu nhờ vào các chương trình hỗ trợ cho lao động nông thôn."], "correctIndex": 2, "explain": ""}, {"question": "Với bối cảnh dân số Việt Nam đang trong thời kỳ dân số vàng ( <img class=\"anh-de\" src=\"data/anh/l6/d453167d97a22e81.png\" alt=\"\" style=\"width:48px;height:22px;vertical-align:middle\"> trong độ tuổi lao động) và <img class=\"anh-de\" src=\"data/anh/l6/179adcfe2a5bcde4.png\" alt=\"\" style=\"width:48px;height:22px;vertical-align:middle\"> lực lượng lao động tập trung tại nông thôn, bạn sẽ đề xuất hành động nào để tận dụng hiệu quà nguồn lao động này nhằm đáp úng yêu cầu phát triển kinh tế số và hội nhập quốc tê?", "choices": ["Xây dựng các chương trình đào tạo kỹ năng công nghệ số, ngoại ngữ, và kỹ năng nghề tại nông thôn, kết hợp với doanh nghiệp để đảm bảo đầu ra việc làm.", "Tập trung phát triển các khu công nghiệp tại thành phố lớn, khuyến khích lao động nông thôn di cư để tiếp cận cơ hội việc làm tốt hơn.", "Mở rộng chính sách hỗ trợ tài chính để lao động nông thôn tham gia các chương trình đào tạo dài hạn ở nước ngoài, nhằm tích lũy kỹ năng và kinh nghiệm quốc tế.", "Phát triển hạ tầng giáo dục chất lượng cao tại nông thôn, với trọng tâm vào giáo dục phổ thông thay vì đào tạo nghề, để chuẩn bị lâu dài cho thế hệ lao động trẻ."], "correctIndex": 0, "explain": "<b><u>Hướng dẫn giải</u></b>"}], "khongXaoTron": true}]};
